package cz.mh.rallye.rallye_backend.participation;
import java.time.*;import java.util.*;import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.SimpleTransactionStatus;
import cz.mh.rallye.rallye_backend.identity.application.*;import cz.mh.rallye.rallye_backend.identity.persistence.*;
import cz.mh.rallye.rallye_backend.crews.persistence.CrewStore;import cz.mh.rallye.rallye_backend.races.persistence.EventStore;import cz.mh.rallye.rallye_backend.races.application.LifecycleService;
import cz.mh.rallye.rallye_backend.participation.application.*;import cz.mh.rallye.rallye_backend.participation.persistence.*;import cz.mh.rallye.rallye_backend.participation.persistence.CrewStartStore.*;
import cz.mh.rallye.rallye_backend.shared.persistence.CommandStore;import cz.mh.rallye.rallye_backend.audit.application.AuditService;import cz.mh.rallye.rallye_backend.templates.persistence.TemplateStore;import cz.mh.rallye.rallye_backend.templates.domain.StageConfiguration;
class CrewStartServiceTest {
 final CrewStartStore store=mock(CrewStartStore.class);final RegistrationStore registrations=mock(RegistrationStore.class);final CrewStore crews=mock(CrewStore.class);final AccountStore accounts=mock(AccountStore.class);final AdminStore roles=mock(AdminStore.class);final CommandStore ledger=mock(CommandStore.class);final AuditService audit=mock(AuditService.class);final EventStore events=mock(EventStore.class);final LifecycleService lifecycle=mock(LifecycleService.class);final PlatformTransactionManager manager=mock(PlatformTransactionManager.class);final CrewStartAttempts attempts=mock(CrewStartAttempts.class);final SecretTokens hashes=new SecretTokens();final CrewStartSecrets secrets=new CrewStartSecrets(hashes);
 final UUID event=UUID.randomUUID(),reg=UUID.randomUUID(),crew=UUID.randomUUID(),stage=UUID.randomUUID();final Instant now=Instant.parse("2026-10-31T12:00:00Z");final AuthService.Principal actor=new AuthService.Principal(UUID.randomUUID(),UUID.randomUUID(),false);
 final Map<UUID,Code> codes=new LinkedHashMap<>();final Map<UUID,Device> devices=new LinkedHashMap<>();final Map<UUID,Command> commands=new HashMap<>();final Map<UUID,Run> runs=new HashMap<>();final List<Progress> progress=new ArrayList<>();final List<Adjustment> adjustments=new ArrayList<>();final AtomicReference<Registration> registration=new AtomicReference<>(new Registration(reg,event,null,0,1,null));CrewStartService service;RaceDeviceAccess access;
 EventStore.Event event(String state,Instant end){return new EventStore.Event(event,UUID.randomUUID(),0,"Race",null,0,state,null,end,0,now,now);}
 void crewOwner(UUID id){var c=new CrewStore.Crew(crew,id,"Crew",null,null,null,null,null,null,null,now,now,0);doReturn(c).when(crews).find(crew);doReturn(c).when(crews).read(crew);}
 Code add(String value,String kind,long generation,long points){var c=new Code(UUID.randomUUID(),reg,kind,generation,"AVAILABLE",value,now.minusSeconds(300),actor.accountId(),null,null,points,null,0);codes.put(c.id(),c);return c;}
 @BeforeEach void setup(){service=new CrewStartService(store,registrations,crews,accounts,roles,ledger,audit,secrets,hashes,attempts,events,lifecycle,Clock.fixed(now,ZoneOffset.UTC),manager);access=new RaceDeviceAccess(store,events,secrets);when(manager.getTransaction(any())).thenAnswer(i->new SimpleTransactionStatus());when(roles.activeVerified(actor.accountId())).thenReturn(true);when(accounts.isActiveSession(any(),any(),any())).thenReturn(true);when(registrations.crew(event,reg)).thenReturn(crew);crewOwner(actor.accountId());when(events.lock(event)).thenReturn(event("RUNNING",now.plusSeconds(3600)));when(events.read(event)).thenAnswer(i->events.lock(event));when(lifecycle.reconcile(any(),any(),anyBoolean(),any())).thenAnswer(i->i.getArgument(0));when(store.registration(eq(reg),anyBoolean())).thenAnswer(i->registration.get());when(store.run(eq(reg),any(),anyBoolean())).thenAnswer(i->runs.get(i.getArgument(1)));when(store.code(eq(reg),any(),anyBoolean())).thenAnswer(i->codes.get(i.getArgument(1)));when(store.availableCode(eq(reg),any())).thenAnswer(i->codes.values().stream().filter(c->c.state().equals("AVAILABLE")&&c.value().equals(i.getArgument(1))).findFirst().orElse(null));when(store.command(eq(actor.accountId()),any())).thenAnswer(i->commands.get(i.getArgument(1)));doAnswer(i->{Command c=i.getArgument(0);commands.put(c.key(),c);return null;}).when(store).insertCommand(any());doAnswer(i->{Run r=i.getArgument(0);runs.put(r.id(),r);return null;}).when(store).insertRun(any());doAnswer(i->{progress.add(i.getArgument(0));return null;}).when(store).insertProgress(any());
  when(store.bindInitialRun(eq(reg),anyLong(),any(),eq(actor.accountId()),any())).thenAnswer(i->{var r=registration.get();if(r.version()!=(Long)i.getArgument(1))return false;registration.set(new Registration(reg,event,i.getArgument(2),1,r.version()+1,i.getArgument(4)));return true;});when(store.advanceDeviceGeneration(eq(reg),anyLong(),anyLong(),any())).thenAnswer(i->{var r=registration.get();if(r.version()!=(Long)i.getArgument(1)||r.deviceGeneration()!=(Long)i.getArgument(2))return false;registration.set(new Registration(reg,event,r.currentRunId(),r.deviceGeneration()+1,r.version()+1,r.startedAt()));return true;});
  when(store.deviceHashExists(any())).thenAnswer(i->devices.values().stream().anyMatch(d->d.hash().equals(i.getArgument(0))));when(store.currentDevice(eq(reg),anyBoolean())).thenAnswer(i->devices.values().stream().filter(d->d.state().equals("ACTIVE")).findFirst().orElse(null));when(store.device(eq(reg),any(),anyBoolean())).thenAnswer(i->devices.get(i.getArgument(1)));when(store.activeDevice(any())).thenAnswer(i->devices.values().stream().filter(d->d.state().equals("ACTIVE")&&d.hash().equals(i.getArgument(0))&&d.generation()==registration.get().deviceGeneration()).findFirst().orElse(null));doAnswer(i->{Device d=i.getArgument(0);devices.put(d.id(),d);return null;}).when(store).insertDevice(any());when(store.revokeDevice(eq(reg),any(),anyLong(),any(),any(),any())).thenAnswer(i->{Device d=devices.get(i.getArgument(1));if(d==null||!d.state().equals("ACTIVE")||d.generation()!=(Long)i.getArgument(2))return false;devices.put(d.id(),new Device(d.id(),reg,d.generation(),d.hash(),"REVOKED",d.createdAt(),i.getArgument(3),d.codeId(),d.label(),i.getArgument(5),i.getArgument(4)));return true;});
  when(store.consumeCode(eq(reg),any(),anyLong(),any(),any())).thenAnswer(i->{Code c=codes.get(i.getArgument(1));if(!c.state().equals("AVAILABLE")||c.version()!=(Long)i.getArgument(2))return false;codes.put(c.id(),new Code(c.id(),reg,c.kind(),c.generation(),"USED",c.value(),c.issuedAt(),c.issuedBy(),i.getArgument(4),i.getArgument(3),c.points(),c.reason(),c.version()+1));return true;});when(store.adjustments(reg)).thenAnswer(i->List.copyOf(adjustments));doAnswer(i->{adjustments.add(i.getArgument(0));return null;}).when(store).insertAdjustment(any());when(store.touchRun(eq(reg),any(),anyLong())).thenAnswer(i->{var r=runs.get(i.getArgument(1));if(r.version()!=(Long)i.getArgument(2))return false;runs.put(r.id(),new Run(r.id(),reg,event,r.ordinal(),r.status(),r.activationGeneration(),r.startedAt(),r.completedAt(),r.endedAt(),r.version()+1));return true;});
  when(events.stages(event)).thenReturn(List.of(new EventStore.Stage(new TemplateStore.Stage(stage,event,1,"First",null,0L,"# Instructions",StageConfiguration.empty()),UUID.randomUUID())));add("ABC123","ORIGINAL",1,0);add("XYZ789","ORIGINAL",2,0);
 }
 String failure(Runnable work){return assertThrows(AuthFailure.class,work::run).code();}
 CrewStartService.RedemptionReceipt start(String token){return service.redeem(actor,event,reg,UUID.randomUUID(),1,"ABC123",token,null);}
 @Test void firstStartUsesEvaluatorAndLeavesSecondCodeAvailable(){var r=start(hashes.create());assertEquals("START",r.effect());assertEquals(now,r.individualStartedAt());assertEquals(1,r.deviceGeneration());assertEquals(0,r.runVersion());assertEquals(2,r.registrationVersion());assertEquals(1,runs.size());assertEquals(1,progress.size());assertEquals("ACTIVE",progress.getFirst().status());assertEquals(now,progress.getFirst().activatedAt());assertEquals(1,codes.values().stream().filter(c->c.state().equals("AVAILABLE")).count());verify(audit).raceDevice(eq(actor.accountId()),eq(AuditService.Event.CREW_INDIVIDUALLY_STARTED),eq(reg),any());}
 @Test void secondOriginalCanBeFirstAndTakeoverDoesNotRestart(){var first=service.redeem(actor,event,reg,UUID.randomUUID(),1,"XYZ789",hashes.create(),null);var before=List.copyOf(progress);var next=service.redeem(actor,event,reg,UUID.randomUUID(),2,"ABC123",hashes.create(),null);assertEquals("TAKEOVER",next.effect());assertEquals(first.runId(),next.runId());assertEquals(first.individualStartedAt(),next.individualStartedAt());assertEquals(first.activationGeneration(),next.activationGeneration());assertEquals(before,progress);assertEquals(1,runs.size());assertEquals(2,next.deviceGeneration());assertEquals("REVOKED",devices.get(first.deviceId()).state());assertTrue(adjustments.isEmpty());}
 @Test void signedCorrectionAppliesOnlyOnceAndReplayIsHistorical(){start(hashes.create());add("EXTRA3","REPLACEMENT",3,-5);UUID key=UUID.randomUUID();String token=hashes.create();var receipt=service.redeem(actor,event,reg,key,2,"extra3",token,"phone");assertEquals("-5",receipt.pointsAdjustment());assertEquals(1,receipt.runVersion());assertEquals(receipt,service.redeem(actor,event,reg,key,2," EXTRA3 ",token,"phone"));assertEquals(1,adjustments.size());assertEquals(2,devices.size());assertEquals("IDEMPOTENCY_CONFLICT",failure(()->service.redeem(actor,event,reg,key,2,"EXTRA3",hashes.create(),"phone")));assertEquals("START_CODE_INVALID",failure(()->service.redeem(actor,event,reg,UUID.randomUUID(),3,"EXTRA3",hashes.create(),null)));}
 @Test void revokedReplayDoesNotReviveAndCredentialCannotBeReused(){UUID key=UUID.randomUUID();String token=hashes.create();var first=service.redeem(actor,event,reg,key,1,"ABC123",token,null);assertEquals("DEVICE_SECRET_REUSED",failure(()->service.redeem(actor,event,reg,UUID.randomUUID(),2,"XYZ789",token,null)));service.redeem(actor,event,reg,UUID.randomUUID(),2,"XYZ789",hashes.create(),null);assertEquals("RACE_DEVICE_REVOKED",failure(()->service.redeem(actor,event,reg,key,1,"ABC123",token,null)));assertEquals("RACE_DEVICE_INVALID",failure(()->access.require(token,reg,first.runId(),1,1)));}
 @Test void endBoundaryAndEarlyAttemptsNeverConsumeCodes(){when(events.lock(event)).thenReturn(event("PLANNED",now.plusSeconds(3600)));assertEquals("RACE_NOT_STARTED",failure(()->start(hashes.create())));when(events.lock(event)).thenReturn(event("RUNNING",now));assertEquals("RACE_ENDED",failure(()->start(hashes.create())));assertTrue(runs.isEmpty());assertTrue(devices.isEmpty());assertTrue(codes.values().stream().allMatch(c->c.state().equals("AVAILABLE")));verifyNoInteractions(audit);}
 @Test void versionPrecedesTimeAndInvalidCodesAreUniform(){when(events.lock(event)).thenReturn(event("ENDED",now));assertEquals("REGISTRATION_VERSION_CONFLICT",failure(()->service.redeem(actor,event,reg,UUID.randomUUID(),0,"ABC123",hashes.create(),null)));when(events.lock(event)).thenReturn(event("RUNNING",now.plusSeconds(10)));assertEquals("START_CODE_INVALID",failure(()->service.redeem(actor,event,reg,UUID.randomUUID(),1,"BAD123",hashes.create(),null)));assertEquals("INVALID_REQUEST",failure(()->service.redeem(actor,event,reg,UUID.randomUUID(),1,"ABC123","short",null)));}
 @Test void adminRoleDoesNotReplaceCaptainAndCaptainChangesImmediately(){when(roles.administrator(actor.accountId())).thenReturn(true);crewOwner(UUID.randomUUID());assertEquals("REGISTRATION_NOT_FOUND",failure(()->start(hashes.create())));assertTrue(runs.isEmpty());}
 @Test void revokeIsSpecificIdempotentAndTakeoverAfterRevokeWorks(){var first=start(hashes.create());when(roles.administrator(actor.accountId())).thenReturn(true);UUID key=UUID.randomUUID();var revoked=service.revoke(actor,event,reg,first.deviceId(),key,2,1,"reason");assertEquals(2,revoked.deviceGeneration());assertEquals(first.runId(),revoked.currentRunId());assertEquals(0,runs.get(first.runId()).version());assertEquals(revoked,service.revoke(actor,event,reg,first.deviceId(),key,2,1,"reason"));var next=service.redeem(actor,event,reg,UUID.randomUUID(),3,"XYZ789",hashes.create(),null);assertEquals(3,next.deviceGeneration());assertEquals(revoked,service.revoke(actor,event,reg,first.deviceId(),key,2,1,"reason"));assertEquals("ACTIVE",devices.get(next.deviceId()).state());assertEquals("REGISTRATION_VERSION_CONFLICT",failure(()->service.revoke(actor,event,reg,first.deviceId(),UUID.randomUUID(),2,1,null)));assertEquals("DEVICE_ALREADY_REVOKED",failure(()->service.revoke(actor,event,reg,first.deviceId(),UUID.randomUUID(),4,1,null)));}
 @Test void revokeRequiresAdminAndMatchingGeneration(){var r=start(hashes.create());assertEquals("ADMIN_REQUIRED",failure(()->service.revoke(actor,event,reg,r.deviceId(),UUID.randomUUID(),2,1,null)));when(roles.administrator(actor.accountId())).thenReturn(true);assertEquals("DEVICE_GENERATION_CONFLICT",failure(()->service.revoke(actor,event,reg,r.deviceId(),UUID.randomUUID(),2,2,null)));assertEquals("RACE_DEVICE_NOT_FOUND",failure(()->service.revoke(actor,event,reg,UUID.randomUUID(),UUID.randomUUID(),2,1,null)));}
 @Test void deviceAuthorizationIsIndependentOfAccountSessionButChecksRunAndActivation(){String token=hashes.create();var first=start(token);when(accounts.isActiveSession(any(),any(),any())).thenReturn(false);assertEquals(first.deviceId(),access.require(token,reg,first.runId(),1,1).deviceId());assertEquals("RACE_RUN_NOT_CURRENT",failure(()->access.require(token,reg,UUID.randomUUID(),1,1)));assertEquals("RACE_ACTIVATION_STALE",failure(()->access.require(token,reg,first.runId(),2,1)));assertEquals("INVALID_CREDENTIALS",failure(()->service.redeem(actor,event,reg,UUID.randomUUID(),2,"XYZ789",hashes.create(),null)));}
 @Test void int64CorrectionOverflowRejectsBeforeDeviceChanges(){var first=start(hashes.create());adjustments.add(new Adjustment(UUID.randomUUID(),reg,UUID.randomUUID(),Long.MAX_VALUE,now,null));add("EXTRA3","REPLACEMENT",3,1);assertEquals("RACE_STATE_UNAVAILABLE",failure(()->service.redeem(actor,event,reg,UUID.randomUUID(),2,"EXTRA3",hashes.create(),null)));assertEquals("ACTIVE",devices.get(first.deviceId()).state());assertEquals(1,devices.size());assertEquals("AVAILABLE",codes.values().stream().filter(c->c.value().equals("EXTRA3")).findFirst().orElseThrow().state());}
 @Test void auditFailureRollsBackAndReceiptsNeverContainSecrets(){String token=hashes.create();doThrow(new IllegalStateException("Injected")).when(audit).raceDevice(any(),any(),any(),any());assertEquals("RACE_STATE_UNAVAILABLE",failure(()->start(token)));verify(manager).rollback(any());for(Command c:commands.values()){assertFalse(c.resultJson().contains(token));assertFalse(c.resultJson().contains("ABC123"));}verify(attempts).account(actor.accountId());}
 @Test void startStatusIsReadOnlyAndNeverReturnsCodesOrHashes(){var initial=service.status(actor,event,reg);assertTrue(initial.canStart());assertFalse(initial.canTakeOver());var first=start(hashes.create());var after=service.status(actor,event,reg);assertFalse(after.canStart());assertTrue(after.canTakeOver());assertEquals(first.deviceId(),after.activeDevice().id());crewOwner(UUID.randomUUID());when(roles.administrator(actor.accountId())).thenReturn(true);assertEquals("NOT_CAPTAIN",service.status(actor,event,reg).blockedReason());}
}
